// ── Interface Builder data model ────────────────────────────────────────────
// Shared between the editor (CreateScreen.tsx's Interface Builder — Design
// canvas + Logic tab) and the runtime (App.tsx, which renders elements and
// interprets workflows during play). Keep both in lockstep with this file
// rather than letting either side drift its own copy of the shape.
//
// Free-form: x/y/w/h are all 0–100, percentages of the Design canvas box.
// No parent/child nesting in v1 — panels are just another positionable box;
// stack anything on top of one with zIndex instead of nesting it inside.
// Deliberately small — one flat ordered step list per interactive element,
// triggered by "On Tap", no guards/conditions. Bubble-style but kept simple.
var IFACE_ACTION_META={openPanel:{label:'Open Panel',icon:'open_in_full',help:'Shows a panel element'},closePanel:{label:'Close Panel',icon:'close_fullscreen',help:'Hides a panel element'},togglePanel:{label:'Toggle Panel',icon:'flip',help:'Shows the panel if hidden, hides it if shown'},showToast:{label:'Show Message',icon:'chat_bubble',help:'Pops up a short message on screen'},fireCustomEvent:{label:'Fire Game Event',icon:'bolt',help:'Runs Interface.OnButton("name", fn) in your Lua script'},playSound:{label:'Play Sound',icon:'volume_up',help:'Plays a sound effect'},wait:{label:'Wait',icon:'timer',help:'Pauses before running the next step'}};var IFACE_ACTION_ORDER=['openPanel','closePanel','togglePanel','showToast','fireCustomEvent','playSound','wait'];var IFACE_KIND_META={button:{label:'Button',icon:'smart_button'},text:{label:'Text',icon:'text_fields'},image:{label:'Image',icon:'image'},panel:{label:'Panel',icon:'dashboard'}};var IFACE_COLOR_SWATCHES=['rgba(0,0,0,0.60)','rgba(255,255,255,0.14)','rgba(30,140,255,0.55)','rgba(255,69,58,0.55)','rgba(52,199,89,0.55)','rgba(255,214,10,0.55)','rgba(191,90,242,0.55)'];// Material Symbol names are lowercase ascii snake_case (e.g. "open_in_full").
